async function inspectResults(provider,btn){
 if(!amAdmin()||demo)throw Error('Connexion externe réservée à l’administration du portail connecté.');
 const clientId=state.clientId,oldLabel=btn.textContent;btn.disabled=true;btn.textContent='Lecture en cours…';
 try{const {data:{session}}=await sb.auth.getSession();const response=await fetch('/api/results',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({provider,clientId})});const result=await response.json();if(!response.ok)throw Error(result.error||'Lecture impossible.');if(state.clientId!==clientId)return;resultsDraft={...result,clientId};
 const body=provider==='ghl'?`<p>Lecture réussie du sous-compte ${h(result.locationId)}. Du ${date(result.from)} au ${date(result.to)}, heure de Toronto.</p><div class="stats-grid">${stat('Nouveaux contacts',num(result.contacts.count),'Contacts créés, pas encore des leads qualifiés')}</div><h3>Sources des nouveaux contacts</h3>${result.canConfigure?button('Choisir les sources et découvertes','oauth-criteria','secondary'):''}${result.contacts.sources.map(s=>`<div class="task-row"><strong>${h(s.name)}</strong><span>${num(s.count)}</span></div>`).join('')||'<p>Aucun nouveau contact dans cette période.</p>'}<h3>Calendriers disponibles</h3>${result.calendars.map(c=>`<p>${h(c.name)}</p>`).join('')||'<p>Aucun calendrier disponible.</p>'}<h3>Étapes du pipeline</h3>${result.pipelines.map(p=>`<p><strong>${h(p.name)}</strong><br>${p.stages.map(s=>h(s.name)).join(' → ')}</p>`).join('')||'<p>Aucun pipeline disponible.</p>'}<div class="notice">${result.configurationPending?'Les sources de leads et calendriers de ce dossier restent à valider. Aucun chiffre n’est proposé au journal.':`${num(result.qualifiedLeads)} contacts GHL dans les sources validées. ${countsLeadFrom(currentLeadCaptureMode(),'ghl')?'Leurs leads peuvent être proposés après revue.':'Leur nombre de leads ne sera pas repris pour cette campagne : source Meta ou non confirmée.'} Calendriers retenus : ${result.discoveryCalendars.map(h).join(", ")}. Les statuts incertains et journées en cours restent à vérifier. Les réservations initiales, réponses, pitchs et contrats restent à saisir; leur première date ne peut pas être déduite d’une étape actuelle. Aucun journal modifié par cette lecture.`}</div><h3>Propositions par journée terminée</h3><div class="table-scroll"><table><thead><tr><th>Jour</th><th>Leads</th><th>Prévues / tenues</th><th></th></tr></thead><tbody>${result.days.map(d=>`<tr><td>${date(d.day)}</td><td>${num(d.leads)}</td><td>${num(d.appointments_due)} / ${num(d.attended)}</td><td>${d.day===result.to?'Journée en cours':button('Préparer la saisie','review-ghl-day','text-btn',d.day)}</td></tr>`).join('')}</tbody></table></div>`:`<p>Lecture réussie : ${h(result.account.name)} · ${h(result.account.currency)} · ${h(result.account.timezone)}.</p><p>Du ${date(result.from)} au ${date(result.to)}. Les dates suivent le fuseau publicitaire; Toronto et New York suivent ici les mêmes journées. Un autre fuseau demande vérification avant reprise.</p><div class="table-scroll"><table><thead><tr><th>Jour</th><th>Dépenses (${h(result.account.currency)})</th><th>Impressions</th><th>Clics</th><th></th></tr></thead><tbody>${result.days.map(d=>`<tr><td>${date(d.day)}</td><td>${num(d.spend)}</td><td>${num(d.impressions)}</td><td>${num(d.clicks)}</td><td>${d.day===result.to?'Journée en cours':result.account.currency==='CAD'&&['America/Toronto','America/New_York'].includes(result.account.timezone)?button('Préparer la saisie','review-meta-day','text-btn',d.day):'Fuseau ou devise à vérifier'}</td></tr>`).join('')}</tbody></table></div><div class="notice">Les conversions attribuées Meta ne sont pas additionnées aux contacts GHL. Les jours absents du rapport restent inconnus. Chaque reprise de dépenses se vérifie avant enregistrement.</div>`;
 document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${provider==='ghl'?'GHL · données reçues':'Meta · dépenses reçues'}</h2><button class="close" data-action="close" aria-label="Fermer">×</button></div><div class="summary-preview">${body}<p class="small muted">Lecture du ${date(result.verifiedAt,true)} · Administration uniquement.</p></div></section></div>`;
 }finally{btn.disabled=false;btn.textContent=oldLabel;await loadConnectionBoard(clientId,true)}
}
function currentLeadCaptureMode(){const c=current();return offerKey(c?.offer)==='97'?campaign97Data(state.data,c.id).settings?.data?.lead_capture_mode:clientProduction(state.data,c?.id).profile?.data?.settings?.lead_capture_mode}
function reviewConnectedDay(day){
 if(!amAdmin()||!resultsDraft||resultsDraft.clientId!==state.clientId)throw Error('Relisez les données connectées de ce dossier.');
 const meta=resultsDraft.provider==='meta';if(meta&&(resultsDraft.account.currency!=='CAD'||!['America/Toronto','America/New_York'].includes(resultsDraft.account.timezone)))throw Error('Devise ou fuseau différent : reprise manuelle requise.');
 const item=resultsDraft.days.find(d=>d.day===day);if(!item||day===resultsDraft.to)throw Error('Choisissez une journée terminée disponible.');
 const old=dailyRows().find(r=>r.report_date===day);modal('daily',old?.id,{report_date:day});
 const proposed=connectedDayProposal(resultsDraft.provider,currentLeadCaptureMode(),item),added=[];
 for(const [key,value] of Object.entries(proposed))if(value!=null&&old?.[key]==null){document.querySelector('[name="'+key+'"]').value=value;added.push(key+'='+value)}
 if(added.length){const note=document.querySelector('[name="note"]');note.value=(note.value?note.value+'\n':'')+'Proposition '+(meta?'Meta '+resultsDraft.account.id:'GHL '+resultsDraft.locationId)+' · '+day+' · '+added.join(', ')+' · lecture '+resultsDraft.verifiedAt;toast('Chiffres connectés proposés dans les champs vides. Vérifiez puis enregistrez.')}else toast('Les chiffres déjà saisis sont conservés.');
 document.querySelector('[name="leads"]').dispatchEvent(new Event('input',{bubbles:true}));
}

function teamMembers(){return rows('team_members').sort((a,b)=>a.name.localeCompare(b.name,'fr'))}
function canEditPerson(member){return amAdmin()||(!state.previewClient&&member?.user_id&&member.user_id===state.user?.id)}
function canWriteShared(){return current()?.work_mode!=='Équipe'||amAdmin()||(!state.previewClient&&teamMembers().some(m=>m.user_id===state.user?.id&&m.team_role==='Responsable'))}
function workModePicker(value='Solo'){return `<fieldset class="offer-picker work-mode-picker wide"><legend>Fonctionnement du dossier</legend><div class="offer-options">${[['Solo','Une personne, un système.'],['Équipe','Un système commun, les chiffres de chacun.']].map(([v,desc])=>`<label class="offer-choice"><input type="radio" name="work_mode" value="${v}" ${value===v?'checked':''}><span class="offer-choice-content"><strong>${v}</strong><small>${desc}</small></span></label>`).join('')}</div></fieldset>`}
function personalReminder(){
 if(current()?.work_mode!=='Équipe'||amAdmin())return '';const mine=teamMembers().find(m=>m.user_id===state.user?.id);if(!mine)return '';const {day,minutes}=torontoClock(),pref=notificationPreferences(),at=Number(pref.daily_time.slice(0,2))*60+Number(pref.daily_time.slice(3,5)),weekday=new Date(day+'T12:00:00Z').getUTCDay();if(!pref.daily||!pref.work_days.includes(weekday)||minutes<at||['En pause','Terminé'].includes(current().status))return '';try{if(localStorage.getItem(reminderStorageKey(day)+':person')==='yes')return ''}catch{}
 const entry=rows('team_daily_reports').find(r=>r.member_id===mine.id&&r.report_date===day);if(entry&&personMetrics.every(([k])=>entry[k]!=null))return '';
 return `<section class="portal-alert" role="status"><span class="reminder-icon">${icon('people')}</span><div><strong>Mes chiffres dans l’équipe</strong><p>Pensez à compléter votre journée personnelle, responsable compris.</p></div><div class="reminder-actions">${button('Entrer mes chiffres','person-today','primary',mine.id)}${button('Demain','dismiss-person','text-btn')}</div></section>`;
}
function teamPage(){
 if(current()?.work_mode!=='Équipe')return empty('Ce dossier fonctionne en solo','Le mode Équipe se choisit dans les paramètres du dossier.');
 const members=teamMembers(),reports=rows('team_daily_reports'),end=kpiEnd,from=periodBounds(reports,end,kpiPeriod).start,mine=members.find(m=>m.user_id===state.user?.id);
 return heading('MON ÉQUIPE','Un système. La contribution de chacun.','Chaque personne, responsable compris, renseigne ses chiffres. La vue est partagée dans ce dossier.',(mine?button('Entrer mes chiffres','person-today','primary',mine.id):'')+(amAdmin()?button('Ajouter une personne','new-member','secondary'):''))+`<div class="notice subtle">Les dépenses publicitaires et nouveaux leads se suivent une seule fois dans Mes chiffres. Les activités personnelles ci-dessous ne sont pas additionnées au parcours commun : un lead transféré entre deux personnes ne doit pas gonfler les résultats.</div><section class="panel team-summary">${periodPicker()}<div class="panel-heading"><div><h2>${h(periodName())}</h2><p>${date(from)} au ${date(end)} · Tous les membres de ce dossier voient cette comparaison.</p></div></div>${members.length?`<div class="table-scroll"><table><thead><tr><th>Personne</th><th>Leads pris en charge</th><th>Tentatives</th><th>Réponses</th><th>Découvertes réservées</th><th>Prévues / tenues</th><th>Présence</th><th>Pitchs</th><th>Contrats</th><th></th></tr></thead><tbody>${members.map(m=>{const s=personSummary(reports,m.id,end,kpiPeriod),t=s.totals;return `<tr><td><strong>${h(m.name)}</strong><small>${h(m.team_role)} · ${s.days}/${s.window_days} jours${!m.user_id?' · Accès à associer':''}</small></td><td>${num(t.leads_assigned)}</td><td>${num(t.calls)}</td><td>${num(t.responses)}</td><td>${num(t.appointments)}</td><td>${num(t.appointments_due)} / ${num(t.attended)}</td><td>${pct(s.showRate)}</td><td>${num(t.pitches)}</td><td>${num(t.signatures)}</td><td>${canEditPerson(m)?button('Saisir','person-today','text-btn',m.id):''}${amAdmin()?button('Modifier la personne','edit-member','text-btn',m.id)+button(m.user_id?'Accès / nouveau lien':'Créer son accès','edit-member-access','text-btn',m.id):''}</td></tr>`}).join('')}</tbody></table></div>`:empty('Préparez votre équipe','Ajoutez aussi le responsable : il disposera de sa propre saisie.')}</section><section class="panel team-journal"><h2>Journal personnel partagé</h2><p>Les champs vides restent inconnus. Chacun modifie uniquement ses propres chiffres; Courtier Growth peut corriger la saisie avec vous.</p>${reports.sort((a,b)=>b.report_date.localeCompare(a.report_date)).slice(0,100).map(r=>{const m=members.find(m=>m.id===r.member_id);return `<div class="task-row"><div><strong>${h(m?.name||'Membre')}</strong><small>${date(r.report_date)} · ${num(r.responses)} réponses · ${num(r.pitches)} pitchs · ${num(r.signatures)} contrats</small></div>${canEditPerson(m)?button('Modifier ma journée','edit-person-day','secondary',r.id):''}</div>`}).join('')||'<p>Aucune journée personnelle enregistrée.</p>'}</section>`;
}

const personSteps=[{title:'Échanger',icon:'people',keys:['leads_assigned','calls','responses']},{title:'Rencontrer',icon:'chat',keys:['appointments','appointments_due','attended']},{title:'Conclure',icon:'check',keys:['pitches','signatures']}];
function personDayForm(v,m,editing){return `<input type="hidden" name="member_id" value="${h(m.id)}"><div class="day-intro wide"><div><span class="eyebrow">MA CONTRIBUTION</span><p>${h(m.name)} · ${h(m.team_role)}</p></div>${field('report_date','Journée','date',v.report_date||torontoClock().day,{required:true,max:torontoClock().day,...(editing?{readonly:true}:{})})}</div><div class="day-progress wide"><span id="person-completion" role="status" aria-live="polite"></span><span>Vide = inconnu · 0 = aucune activité</span><progress id="person-progress" max="8" value="0" aria-label="Chiffres personnels renseignés"></progress></div><nav class="day-steps person-steps wide" aria-label="Étapes de ma saisie">${personSteps.map((s,i)=>`<button type="button" class="day-step" data-action="person-step" data-id="${i}"><span>${i+1}</span>${s.title}</button>`).join('')}</nav>${personSteps.map((s,i)=>`<section class="day-panel wide" data-person-panel="${i}" ${i?'hidden':''}><div class="day-panel-heading"><span class="day-icon">${icon(s.icon)}</span><div><small>ÉTAPE ${i+1} SUR 3</small><h3>${s.title}</h3></div></div>${s.keys.map(k=>dayMetric([k,personMetrics.find(([key])=>key===k)[1],k==='leads_assigned'?'Vos prises en charge, sans modifier les nouveaux leads communs.':'Votre activité personnelle du jour.'],v)).join('')}${i===1?'<div class="day-feedback" id="person-show">Présence cible : 85 %</div>':''}${i===2?area('note','Mon observation / besoin d’aide',v.note,true):''}</section>`).join('')}<p class="day-help wide">Le responsable remplit aussi sa propre journée. Les chiffres personnels ne sont pas additionnés au parcours commun.</p>`}
function showPersonStep(index){const f=document.querySelector('#record-form[data-kind="person-day"]');if(!f)return;index=Math.max(0,Math.min(2,index));f.dataset.step=index;f.querySelectorAll('[data-person-panel]').forEach((p,i)=>p.hidden=i!==index);f.querySelectorAll('[data-action="person-step"]').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-current',i===index?'step':'false')});f.querySelector('#person-position').textContent=(index+1)+' / 3';f.querySelector('[data-action="person-prev"]').disabled=index===0;f.querySelector('[data-action="person-next"]').disabled=index===2;}
function updatePersonProgress(){const f=document.querySelector('#record-form[data-kind="person-day"]');if(!f)return;const n=personMetrics.filter(([k])=>f.elements[k].value!=='').length;f.querySelector('#person-completion').textContent=n+' / 8 chiffres renseignés';f.querySelector('#person-progress').value=n;const due=f.elements.appointments_due.value,held=f.elements.attended.value;f.querySelector('#person-show').textContent=due!==''&&Number(due)>0&&held!==''?'Présence : '+pct(Number(held)/Number(due))+' · Cible : 85 %':'Présence cible : 85 %';}

async function oauthRequest(body){if(!amAdmin()||demo)throw Error('Connexion externe réservée à l’administration du portail connecté.');const {data:{session}}=await sb.auth.getSession();const r=await fetch('/api/oauth',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw Error(result.error||'Connexion impossible.');return result}
function oauthModal(title,body){document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${h(title)}</h2><button class="close" data-action="close" aria-label="Fermer">×</button></div><div class="summary-preview">${body}</div></section></div>`}
async function openOAuth(provider){
 if(!amAdmin())return;const label=provider==='ghl'?'GHL / Ava':'Meta Ads';
 if(demo){oauthModal('Connecter '+label,`<p>Dans le portail connecté, vous autorisez ${h(label)}, choisissez le compte et confirmez le dossier.</p><div class="notice">Démonstration uniquement. Aucune connexion externe créée.</div>`);return}
 const cid=state.clientId,{data:{session}}=await sb.auth.getSession();const r=await fetch('/api/oauth?clientId='+encodeURIComponent(cid),{headers:{Authorization:'Bearer '+session.access_token}}),s=await r.json();if(!r.ok)throw Error(s.error||'Configuration indisponible.');if(state.clientId!==cid)return;
 const connection=s.connections.find(c=>c.provider===provider),ready=s.providers[provider]?.ready;
 oauthModal('Connecter '+label,`<p>Dossier : <strong>${h(current().name)}</strong></p>${connection?`<div class="notice">Compte associé : ${h(connection.account_name)} · ${h(connection.account_id)}<br>Autorisation valable jusqu’au ${date(connection.expires_at,true)}.</div>`:''}<ol><li>Connectez-vous à ${h(label)}.</li><li>Choisissez le sous-compte ou compte publicitaire du client.</li><li>Confirmez l’association dans le portail.</li></ol><p>Lecture seule. Les chiffres déjà saisis restent conservés.</p>${ready?button(connection?'Reconnecter '+label:'Continuer vers '+label,'oauth-start','primary',provider):`<div class="notice">Activation en cours par Courtier Growth. ${provider==='ghl'?'Le compte développeur GHL et son application doivent être configurés.':'Le profil développeur Meta et les autorisations de l’application doivent être configurés.'} Les données déjà enregistrées restent disponibles.</div>`}`);
}
async function beginOAuth(provider,btn){btn.disabled=true;try{const result=await oauthRequest({action:'start',provider,clientId:state.clientId});const url=new URL(result.url),expected=provider==='ghl'?'marketplace.gohighlevel.com':'www.facebook.com';if(url.protocol!=='https:'||url.hostname!==expected)throw Error('Adresse de connexion invalide.');location.assign(url.href)}catch(e){btn.disabled=false;throw e}}
async function resumeOAuth(){const q=new URLSearchParams(location.search),pendingId=q.get('oauth_pending'),error=q.get('oauth_error');if(!pendingId&&!error)return;history.replaceState(null,'',location.pathname);if(error){toast(error.slice(0,300),true);return}try{const p=await oauthRequest({action:'preview',pendingId});oauthSelection=p;state.clientId=p.client.id;state.page='connections';render();oauthModal('Confirmer le compte du client',`<p>Associer ${p.provider==='ghl'?'GHL / Ava':'Meta Ads'} à <strong>${h(p.client.name)}</strong>.</p>${p.currentAccountId?`<p>Compte actuel : ${h(p.currentAccountId)}. Un autre choix remplacera cette association.</p>`:''}<label class="field"><span>Compte autorisé</span><select id="oauth-account"><option value="">Choisir un compte</option>${p.accounts.map(a=>`<option value="${h(a.id)}">${h(a.name)} · ${h(a.id)}${a.currency?' · '+h(a.currency):''}</option>`).join('')}</select></label><p>Vérifiez le nom et l’identifiant avant de confirmer. Les chiffres enregistrés restent conservés.</p>${button('Associer ce compte au client','oauth-confirm','primary')}`)}catch(e){toast(e.message,true)}}
async function confirmOAuth(btn){if(!oauthSelection||oauthSelection.client.id!==state.clientId)throw Error('Recommencez la connexion depuis le bon dossier.');const accountId=document.querySelector('#oauth-account')?.value;if(!accountId)throw Error('Choisissez un compte autorisé.');btn.disabled=true;try{await oauthRequest({action:'confirm',pendingId:oauthSelection.pendingId,accountId});oauthSelection=null;document.querySelector('#modal-root').innerHTML='';await refresh();toast('Compte associé. Vérifiez maintenant ses données et les sources de vos KPI.')}finally{btn.disabled=false}}

function openCriteria(){if(!amAdmin()||!resultsDraft?.canConfigure||resultsDraft.clientId!==state.clientId)throw Error('Relisez les données du compte connecté.');const r=resultsDraft;oauthModal('Quels résultats compter ?',`<p>Dossier : <strong>${h(current().name)}</strong>. Choisissez uniquement les leads de campagne et les calendriers de découverte.</p><fieldset><legend>Sources de leads</legend>${r.contacts.sources.filter(s=>s.name!=='Non renseignée').map(s=>`<label class="task-row"><input type="checkbox" name="oauth-source" value="${h(s.name)}" ${r.leadSources.includes(s.name)?'checked':''}><span>${h(s.name)} · ${num(s.count)}</span></label>`).join('')}</fieldset><fieldset><legend>Calendriers de découverte</legend>${r.calendars.map(c=>`<label class="task-row"><input type="checkbox" name="oauth-calendar" value="${h(c.name)}" ${r.discoveryCalendars.includes(c.name)?'checked':''}><span>${h(c.name)}</span></label>`).join('')}</fieldset><p>Les pitchs, visites et rappels ne sont pas des appels découverte. Les contacts sans source restent à vérifier.</p>${button('Confirmer ces sources et calendriers','oauth-save-criteria','primary')}`)}
async function saveCriteria(btn){if(!resultsDraft?.canConfigure||resultsDraft.clientId!==state.clientId)throw Error('Recommencez depuis ce dossier.');btn.disabled=true;try{const leadSources=[...document.querySelectorAll('[name="oauth-source"]:checked')].map(e=>e.value),calendarNames=[...document.querySelectorAll('[name="oauth-calendar"]:checked')].map(e=>e.value);await oauthRequest({action:'criteria',clientId:state.clientId,leadSources,calendarNames});document.querySelector('#modal-root').innerHTML='';toast('Critères enregistrés. Relisez les données pour préparer les journées.')}finally{btn.disabled=false}}

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.sidebar.open')){document.querySelector('[data-action=close-menu]')?.click()}});
document.addEventListener('click',e=>{const production=e.target.closest('[data-hub-production]'),campaign=e.target.closest('[data-hub-c97]');if(production&&current()&&hasCapability(current().offer,'dfy_production')){selectProductionView(state.user?.id,state.clientId,production.dataset.hubProduction);state.page='production';render();document.querySelector('#main-content h1')?.focus();return}if(campaign&&current()&&hasCapability(current().offer,'campaign97')){selectCampaign97View(state.user?.id,state.clientId,campaign.dataset.hubC97);state.page='onboarding';render();document.querySelector('#main-content h1')?.focus()}});

function syncMenuAccessibility(){const menu=document.querySelector('.sidebar'),main=document.querySelector('.main');if(!menu||!main)return;const desktop=window.matchMedia?.('(min-width:1101px)').matches??window.innerWidth>=1101,open=menu.classList.contains('open');menu.inert=!desktop&&!open;main.inert=!desktop&&open;}
window.addEventListener('resize',syncMenuAccessibility);
document.addEventListener('keydown',e=>{const menu=document.querySelector('.sidebar.open');if(e.key!=='Tab'||!menu)return;const nodes=[...menu.querySelectorAll('button,a[href],select,summary')].filter(n=>!n.disabled&&n.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}});
